/**
 * Sets the zip bomb threshold (characters before check activates).
 *
 * @param zipBombThreshold zip bomb threshold
 */
public void setZipBombThreshold(long zipBombThreshold) {
    this.zipBombThreshold = zipBombThreshold;
}
